int fd = 4;
off_t offset = 0;
off_t len = 8192;

// Advise the kernel of expected sequential reads
int ret_seq = arm_fadvise(
    fd,
    offset,
    len,
    POSIX_FADV_SEQUENTIAL
);

// Preload specific region into page cache
int ret_will = arm_fadvise(
    fd,
    0,
    len,
    POSIX_FADV_WILLNEED
);

// Release specified pages from cache
arm_fadvise(fd, offset, len, POSIX_FADV_DONTNEED);

// Resume default/no-advice behavior
arm_fadvise(fd, 0, 0, POSIX_FADV_NORMAL);
